using System.Security.Claims;
using Microsoft.AspNetCore.Authorization;
using Microsoft.AspNetCore.Mvc;
using Microsoft.EntityFrameworkCore;
using OmgtuPortal.Data;
using OmgtuPortal.University;

namespace OmgtuPortal.Controllers;

/// <summary>
/// Эндпоинты преподавателя. Доступ: роли teacher и admin.
/// </summary>
[ApiController]
[Route("api/teacher")]
[Authorize(Roles = "teacher,admin")]
public class TeacherController(
    IUniversityClient universityClient,
    AppDbContext db,
    AppSettings settings) : ControllerBase
{
    [HttpGet("groups")]
    public async Task<IActionResult> GetGroups()
    {
        return Ok(await universityClient.GetStudentGroupsAsync());
    }

    /// <summary>
    /// Загрузка контрольной работы. Файл сохраняется на диск, метаданные — в БД.
    /// </summary>
    [HttpPost("control-works")]
    [RequestSizeLimit(50 * 1024 * 1024)]
    public async Task<IActionResult> UploadControlWork(
        [FromForm] string title,
        [FromForm] string groupId,
        IFormFile file)
    {
        if (file.Length == 0)
            return BadRequest(new { Error = "Файл пустой" });

        var maxBytes = settings.MaxFileSizeMb * 1024 * 1024;
        if (file.Length > maxBytes)
            return BadRequest(new { Error = $"Файл превышает {settings.MaxFileSizeMb} МБ" });

        var uploadsDir = Path.Combine(Directory.GetCurrentDirectory(), settings.UploadsPath);
        Directory.CreateDirectory(uploadsDir);

        var storedName = $"{Guid.NewGuid()}{Path.GetExtension(file.FileName)}";
        var storedPath = Path.Combine(uploadsDir, storedName);

        await using (var stream = new FileStream(storedPath, FileMode.Create))
        {
            await file.CopyToAsync(stream);
        }

        var userId = User.FindFirstValue(ClaimTypes.NameIdentifier)
                     ?? User.FindFirstValue("sub")
                     ?? "unknown";

        var controlWork = new ControlWork
        {
            Id = Guid.NewGuid(),
            Title = title,
            GroupId = groupId,
            FileName = file.FileName,
            StoredPath = storedName,
            ContentType = file.ContentType,
            FileSize = file.Length,
            UploadedBy = userId,
            UploadedAt = DateTime.UtcNow,
        };

        db.ControlWorks.Add(controlWork);
        await db.SaveChangesAsync();

        return Created($"/api/teacher/control-works/{controlWork.Id}", new
        {
            controlWork.Id,
            controlWork.Title,
            controlWork.GroupId,
            controlWork.FileName,
            controlWork.FileSize,
            controlWork.UploadedAt,
        });
    }

    /// <summary>
    /// Список контрольных работ (опционально по группе).
    /// </summary>
    [HttpGet("control-works")]
    public async Task<IActionResult> GetControlWorks([FromQuery] string? groupId)
    {
        var query = db.ControlWorks.AsQueryable();

        if (!string.IsNullOrEmpty(groupId))
            query = query.Where(c => c.GroupId == groupId);

        var list = await query
            .OrderByDescending(c => c.UploadedAt)
            .Select(c => new
            {
                c.Id,
                c.Title,
                c.GroupId,
                c.FileName,
                c.FileSize,
                c.UploadedAt,
            })
            .ToListAsync();

        return Ok(list);
    }
}

