        var list = await query
            .OrderByDescending(c => c.UploadedAt)
            .Select(c => new
            {
                c.Id,
                c.SubjectId,
                c.GroupId,
                c.FileName,
                c.FileSize,
                c.UploadedAt,
            })
            .ToListAsync();

        return Ok(list);
    }
}

